#include <iostream>
using namespace std;

class Bank {
public:
    void deposit(int amount) {
        balance += amount;
    }
    void withdraw(int amount) {
        if (balance >= amount) {
            balance -= amount;
        }
    }
    int getBalance() {
        return balance;
    }
private:
    int balance = 0;
};

int main() {
    Bank bank;
    bank.deposit(1000);
    cout << "Balance: " << bank.getBalance() << endl;
    bank.withdraw(500);
    cout << "Balance: " << bank.getBalance() << endl;
    return 0;
}

class Calculator {
public:
    int add(int a, int b) { return a + b; }
    int subtract(int a, int b) { return a - b; }
    int multiply(int a, int b) { return a * b; }
    int divide(int a, int b) { if (b == 0) { throw "Division by zero!"; } return a / b; }
};

int main() {
    Calculator calc;
    std::cout << calc.add(5, 3) << std::endl;
    std::cout << calc.subtract(10, 4) << std::endl;
    std::cout << calc.multiply(7, 2) << std::endl;
    try {
        std::cout << calc.divide(9, 0) << std::endl;
    } catch (const char* e) {
        std::cerr << e << std::endl;
    }
    return 0;
}

